/**
 * A block that is only `-flag` tokens (e.g. the standalone `-nocard` paragraph
 * `build-css-api.ts` emits before an `@example` fence). Shares the flag grammar with
 * `tools/demo/src/index.ts`'s `parseFlags` (`/-[a-z][a-z0-9-]*/gu`) — matches `hasProseWords` would
 * otherwise wave through, since stripping the leading `-` still leaves Latin letters.
 */
const isFlagOnly = (text: string): boolean => /^(?:-[a-z][a-z0-9-]*)(?:\s+-[a-z][a-z0-9-]*)*$/u.test(text);

